package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.OriginRefVO;

class OriginRefValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of origin ref of observed source")
  void test_origin_ref_value_holder_assign_plain_value() {
    Object holder = new Object();
    OriginRefValueHolder<Object> value = new OriginRefValueHolder<>(holder);
    Assertions.assertSame(holder, value.originRef("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getOriginRefValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getOriginRef().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.originRefNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getOriginRefValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getOriginRef().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of origin ref of observed source")
  void test_origin_ref_value_holder_assign_value_object() {
    Object holder = new Object();
    OriginRefValueHolder<Object> value = new OriginRefValueHolder<>(holder);
    OriginRefVO vo = OriginRefVO.from("one");
    Assertions.assertFalse(value.getOriginRefValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.originRef(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getOriginRefValue().orElseThrow());
    Assertions.assertSame(holder, value.originRef(Optional.empty()));
    Assertions.assertFalse(value.getOriginRefValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.originRef(Optional.of(vo)));
    Assertions.assertSame(vo, value.getOriginRefValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of origin ref of observed source against the original")
  void test_origin_ref_value_holder_read() {
    Object holder = new Object();
    OriginRefValueHolder<Object> value = new OriginRefValueHolder<>(holder);
    OriginRefVO vo = OriginRefVO.from("one");
    OriginRefVO other = OriginRefVO.from("one");
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getOriginRefValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readOriginRef(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readOriginRef(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.originRef(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readOriginRef(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readOriginRef(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of origin ref of observed source")
  void test_origin_ref_value_holder_unset() {
    Object holder = new Object();
    OriginRefValueHolder<Object> value = new OriginRefValueHolder<>(holder);
    OriginRefVO vo = OriginRefVO.from("one");
    value.originRef(vo);
    Assertions.assertSame(holder, value.unsetOriginRefIfMatches("originRef_other"));
    Assertions.assertTrue(value.getOriginRefValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetOriginRefIfMatches("originRef"));
    Assertions.assertFalse(value.getOriginRefValue().isPresent(),
        "The field name must clear the value");
    value.originRef(vo);
    Assertions.assertSame(holder, value.unsetOriginRef());
    Assertions.assertFalse(value.getOriginRefValue().isPresent(), "Unset must clear the value");
  }
}
